import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    sizes = list(map(int, data[1:1 + n]))

    substituir = 0
    consertar = 0
    for x in sizes:
        if x < 50:
            substituir += 1
        elif x < 85:
            consertar += 1

    print(substituir, consertar)

if __name__ == "__main__":
    main()
